                <label htmlFor={`player-${i}`}>Player {i + 1}</label>
                <input
                  className="control"
                  id={`player-${i}`}
                  value={draft}
                  onChange={(e) => {
                    const copy = [...drafts];
                    copy[i] = e.currentTarget.value;
                    setDrafts(copy);
                  }}
                />
              </div>
            ))}
          </div>
