 31	  const pending = useRef<() => void>(() => {});
 32	  function announce(text: string) {
 33	    setNotice(text);
 34	    setAnnouncement((n) => n + 1);
 35	  }
 36	  useEffect(() => {
 37	    heading.current?.focus();
 38	  }, [t === null ? 'setup' : t.phase]);
 39	  function confirm(action: () => void) {
 40	    if (t && t.phase !== 'complete') {
 41	      pending.current = action;
 42	      dialog.current?.showModal();
 43	    } else action();
 44	  }
 45	  function start(drafts: string[], count: number) {
 46	    const result = normalizeNames(drafts.slice(0, count));
 47	    if (result.error) {
 48	      announce(result.error);
 49	      return;
 50	    }
 51	    const codes: string[] = [];
 52	    for (let i = 0; i < count - 1; i++) {
 53	      let code: string;
 54	      do {
 55	        code = freshBoardCode(roundSize(count, i));
 56	      } while (codes.includes(code));
 57	      codes.push(code);
 58	    }
