.controls {
  display: flex;
  align-items: end;
  flex-wrap: wrap;
  gap: 12px;
  margin-bottom: 16px;
}
.size-control {
  display: flex;
  align-items: center;
  gap: 12px;
}
@media (max-width: 599px) {
  .controls {
    align-items: stretch;
  }
  .size-control {
    width: 100%;
    justify-content: space-between;
  }
  .controls > button {
    flex: 1;
  }
}

